//! Hand-rolled bitflag newtypes for the status words.
//!
//! The link has four of them (STATUS flags, slot status, unit status,
//! cross-check) plus the capability word, all small and all frozen by
//! the tag table, so they are generated by one macro here instead of
//! pulling in a dependency (the crate has none).

/// Define a bitflag newtype over an unsigned integer.
///
/// The generated type keeps the raw word (no value is ever rejected: a
/// newer plane may set bits this build does not know) and offers the
/// usual set operations plus `|`, `&` and `!`.
macro_rules! bitflags {
    (
        $(#[$outer:meta])*
        $name:ident($ty:ty) {
            $( $(#[$inner:meta])* const $flag:ident = $bit:expr; )*
        }
    ) => {
        $(#[$outer])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Default)]
        pub struct $name(pub $ty);

        impl $name {
            $( $(#[$inner])* pub const $flag: $name = $name(1 << $bit); )*

            /// No bits set.
            pub const NONE: $name = $name(0);

            /// Every bit this build knows.
            pub const KNOWN: $name = $name(0 $( | (1 << $bit) )*);

            /// The raw word as it travels on the wire.
            pub const fn bits(self) -> $ty {
                self.0
            }

            /// Wrap a raw word, unknown bits included.
            pub const fn from_bits(bits: $ty) -> Self {
                $name(bits)
            }

            /// True when every bit of `other` is set.
            pub const fn contains(self, other: Self) -> bool {
                self.0 & other.0 == other.0
            }

            /// True when any bit of `other` is set.
            pub const fn intersects(self, other: Self) -> bool {
                self.0 & other.0 != 0
            }

            /// True when no bit is set.
            pub const fn is_empty(self) -> bool {
                self.0 == 0
            }

            /// Set the bits of `other`.
            pub const fn with(self, other: Self) -> Self {
                $name(self.0 | other.0)
            }

            /// Clear the bits of `other`.
            pub const fn without(self, other: Self) -> Self {
                $name(self.0 & !other.0)
            }

            /// Set or clear the bits of `other`.
            pub const fn set(self, other: Self, on: bool) -> Self {
                if on { self.with(other) } else { self.without(other) }
            }

            /// Bits set that this build has no name for.
            pub const fn unknown_bits(self) -> $ty {
                self.0 & !Self::KNOWN.0
            }
        }

        impl core::ops::BitOr for $name {
            type Output = Self;
            fn bitor(self, other: Self) -> Self {
                self.with(other)
            }
        }

        impl core::ops::BitOrAssign for $name {
            fn bitor_assign(&mut self, other: Self) {
                self.0 |= other.0;
            }
        }

        impl core::ops::BitAnd for $name {
            type Output = Self;
            fn bitand(self, other: Self) -> Self {
                $name(self.0 & other.0)
            }
        }

        impl core::ops::Not for $name {
            type Output = Self;
            fn not(self) -> Self {
                $name(!self.0)
            }
        }

        impl From<$ty> for $name {
            fn from(bits: $ty) -> Self {
                $name(bits)
            }
        }

        impl From<$name> for $ty {
            fn from(flags: $name) -> $ty {
                flags.0
            }
        }
    };
}

bitflags! {
    /// INFO 0x06 capabilities: what this plane can do.
    Capabilities(u32) {
        /// Node control: the per-slot sequences (on, off, press).
        const NODE_CONTROL = 0;
        /// Per-slot power limit (INA238 alert).
        const POWER_LIMIT = 1;
        /// Per-unit hot-swap control (U_OFF, hot-swap reset).
        const UNIT_HOT_SWAP = 2;
        /// Press deadline hardware (PRESS_TRIG, ADR 0002).
        const PRESS_DEADLINE = 3;
        /// Firmware update over the link (FW block).
        const FIRMWARE_UPDATE = 4;
    }
}

bitflags! {
    /// STATUS 0x13 plane flags.
    StatusFlags(u16) {
        /// At least one slot is in fault.
        const ANY_SLOT_FAULT = 0;
        /// At least one unit is in fault.
        const ANY_UNIT_FAULT = 1;
        /// Unacknowledged events exist; EXP_INT is asserted.
        const EVENTS_PENDING = 2;
        /// A sequence is running on some slot.
        const SEQUENCE_RUNNING = 3;
        /// Config in RAM differs from the stored set.
        const CONFIG_DIRTY = 4;
        /// A firmware update is in progress.
        const UPDATE_IN_PROGRESS = 5;
        /// The running image is unconfirmed (probation).
        const UNCONFIRMED_IMAGE = 6;
        /// Intended state lost: the core lost power, OFF slots came
        /// back ON, the controller re-applies what it wanted.
        const INTENDED_STATE_LOST = 7;
    }
}

bitflags! {
    /// SLOT 0x20 slot status (also the status word of a SUMMARY
    /// record).
    SlotStatus(u16) {
        /// A module answered on the slot's module ID.
        const PRESENT = 0;
        /// Enabled: the slot's OFF line is released.
        const ENABLED = 1;
        /// Hot-swap PGD.
        const PGD = 2;
        /// The module reports PGOOD.
        const MODULE_PGOOD = 3;
        /// Overvoltage latch is set.
        const OV_LATCHED = 4;
        /// The power limit tripped.
        const POWER_LIMIT_TRIPPED = 5;
        /// The hot-swap is retrying.
        const RETRYING = 6;
        /// A sequence is running on this slot.
        const SEQUENCE_RUNNING = 7;
        /// Module run is off (RUNOFF asserted).
        const MODULE_RUN_OFF = 8;
        /// The slot is disarmed (DISARM asserted).
        const DISARMED = 9;
    }
}

bitflags! {
    /// UNIT 0x30 unit status.
    UnitStatus(u16) {
        /// The unit answers on the chain.
        const PRESENT = 0;
        /// The unit was present and is not answering any more.
        const LOST = 1;
        /// The unit came back at hardware defaults (expander reset).
        const RESET_SEEN = 2;
        /// The unit's expander reads and writes.
        const EXPANDER_OK = 3;
        /// The unit's input INA238 reads.
        const INPUT_INA238_OK = 4;
        /// The unit's hot-swap reports PGD.
        const HOT_SWAP_PGD = 5;
        /// U_OFF is asserted (the unit's input is commanded off).
        const U_OFF_ASSERTED = 6;
        /// The unit's hot-swap latched off (LM5069-1).
        const HOT_SWAP_LATCHED_OFF = 7;
    }
}

bitflags! {
    /// SLOT 0x2C cross-check flags: the LED against the rail.
    CrossCheck(u8) {
        /// The host LED is lit while the slot draws no current.
        const LED_AT_ZERO_CURRENT = 0;
        /// The host LED is lit while the slot is commanded off.
        const LED_WHILE_OFF = 1;
        /// No LED came back after a power-cycle.
        const NO_LED_AFTER_CYCLE = 2;
    }
}

bitflags! {
    /// INFO 0x07 units present, and the slot bitmap of CTRL 0x4B.
    /// Bit `n` is unit `n` (0-3) or slot `n` (0-7).
    IndexBitmap(u8) {
        /// Index 0.
        const I0 = 0;
        /// Index 1.
        const I1 = 1;
        /// Index 2.
        const I2 = 2;
        /// Index 3.
        const I3 = 3;
        /// Index 4.
        const I4 = 4;
        /// Index 5.
        const I5 = 5;
        /// Index 6.
        const I6 = 6;
        /// Index 7.
        const I7 = 7;
    }
}

impl IndexBitmap {
    /// True when index `n` (0-7) is set.
    pub const fn has(self, n: u8) -> bool {
        n < 8 && self.0 & (1 << n) != 0
    }

    /// The same bitmap with index `n` (0-7) set.
    pub const fn plus(self, n: u8) -> Self {
        if n < 8 {
            IndexBitmap(self.0 | (1 << n))
        } else {
            self
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn set_operations() {
        let f = StatusFlags::EVENTS_PENDING | StatusFlags::CONFIG_DIRTY;
        assert_eq!(f.bits(), 0b0001_0100);
        assert!(f.contains(StatusFlags::EVENTS_PENDING));
        assert!(!f.contains(StatusFlags::ANY_SLOT_FAULT));
        assert!(f.intersects(StatusFlags::CONFIG_DIRTY | StatusFlags::ANY_SLOT_FAULT));
        assert!(
            f.without(StatusFlags::CONFIG_DIRTY)
                .contains(StatusFlags::EVENTS_PENDING)
        );
        assert!(StatusFlags::NONE.is_empty());
        assert_eq!(
            StatusFlags::NONE.set(StatusFlags::CONFIG_DIRTY, true),
            StatusFlags::CONFIG_DIRTY
        );
    }

    #[test]
    fn unknown_bits_survive() {
        let raw = SlotStatus::from_bits(0x8000 | SlotStatus::PRESENT.bits());
        assert!(raw.contains(SlotStatus::PRESENT));
        assert_eq!(raw.unknown_bits(), 0x8000);
        assert_eq!(raw.bits(), 0x8001);
    }

    #[test]
    fn index_bitmap() {
        let m = IndexBitmap::NONE.plus(0).plus(7).plus(9);
        assert_eq!(m.bits(), 0b1000_0001);
        assert!(m.has(0) && m.has(7));
        assert!(!m.has(3) && !m.has(8));
    }
}
